export const TrackDataProviders: any = {
  CETUS: 'a',
  DEEPBOOK: 'b',
  DEEPBOOKV3: 'c',
  KRIYA: 'd',
  KRIYAV3: 'e',
  FLOWX: 'f',
  FLOWXV3: 'g',
  AFTERMATH: 'h',
  TURBOS: 'i',
  HAEDAL: 'j',
  HAEDALPMM: 'k',
  VOLO: 'l',
  AFSUI: 'm',
  BLUEMOVE: 'n',
  SCALLOP: 'o',
  SPRINGSUI: 'p',
  BLUEFIN: 'q',
  ALPHAFI: 'r',
  STEAMM: 's',
  METASTABLE: 't',
  OBRIC: 'u'
}

export function trackShioEvent(type: string, status: boolean, tx: string) {
  if (typeof window !== 'undefined' && (window as any).gtag) {
    ;(window as any).gtag('event', 'track_shio_status', {
      operation_type: type,
      shio_enabled: status,
      tx_hash: tx
    })
  }
}

type CommonTrackData = {
  action: string
  txHash: string
  actionTime: number
}

type SwapTrackData = CommonTrackData & {
  isOpenAggregator: boolean // 是否开启Aggregator
  isDowngrade: boolean // 是否降级
  providers: string[] // 开启的路径
  // errorMsg: string
  fromCoin?: string // 用-分割，后面加数量
  toCoin?: string // 用-分割, 后面加数量
  // acountIn?: string
  // amountOut?: string
  isError: boolean
  errorMsg1?: string
  errorMsg2?: string
  errorMsg3?: string
  errorMsg4?: string
  errorMsg5?: string
  useMev?: boolean
  useFastMode?: boolean
}

export function trackTransaction(data: SwapTrackData) {
  console.log('🚀 ~ file: gtag.ts:30 ~ trackTransaction ~ data:', data)
  const providerArr = data.providers.map((item: string) => TrackDataProviders?.[item])
  const providerText = providerArr.join('')

  console.log('🚀 ~ file: gtsag.ts:30 ~ trackTransaction ~ final data:', {
    ...data,
    providers: providerText
  })

  if (typeof window !== 'undefined' && (window as any).gtag) {
    ;(window as any).gtag('event', 'track_transaction', {
      ...data,
      providers: providerText
    })
  }
}

export function trackWalletConnect({ walletName, walletAddress }: { walletName: string; walletAddress: string }) {
  if (typeof window !== 'undefined' && (window as any).gtag) {
    ;(window as any).gtag('event', 'wallet_connection', {
      walletName,
      walletAddress
    })
  }
}
